#![cfg_attr(all(windows, not(debug_assertions)), windows_subsystem = "windows")]
use std::{
    env,
    fs::OpenOptions,
    io::{Read, Write},
    path::PathBuf,
};

#[allow(
    clippy::disallowed_methods,
    reason = "Standalone test emitter cannot use the Bun runtime's file layer"
)]
fn generated_file_metadata(path: &std::path::Path) -> std::io::Result<std::fs::Metadata> {
    std::fs::symlink_metadata(path)
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args: Vec<_> = env::args_os().skip(1).collect();
    if args.len() == 1 && args[0] == "--stdout" {
        std::io::stdout().write_all(b"synthetic subprocess output")?;
        std::io::stdout().flush()?;
        return Ok(());
    }
    if args.len() == 1 && args[0] == "--stderr" {
        std::io::stderr().write_all(b"synthetic subprocess output")?;
        std::io::stderr().flush()?;
        return Ok(());
    }
    if args.len() != 2 || args[0] != "--generate" {
        return Err("--stdout | --stderr | --generate ABSOLUTE_NEW_TEST".into());
    }
    let path = PathBuf::from(&args[1]);
    if !path.is_absolute() {
        return Err("absolute test path required".into());
    }
    let emitter = serde_json::to_string(&env::current_exe()?.to_string_lossy())?;
    let reserved = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .ancestors()
        .nth(3)
        .ok_or("fixture checkout root")?
        .join("test/js/bun/spawn/subprocess-late-stdio.generated.test.ts");
    const STAMP: &[u8] = b"// Generated by subprocess-late-stdio-fixture.\n";
    let reuse = path == reserved;
    if reuse {
        match generated_file_metadata(&path) {
            Ok(meta) => {
                #[cfg(windows)]
                {
                    use std::os::windows::fs::MetadataExt;
                    if meta.file_attributes() & 0x400 != 0 {
                        return Err("reserved test is a reparse point".into());
                    }
                }
                if !meta.file_type().is_file() || meta.file_type().is_symlink() {
                    return Err("reserved test is not a regular file".into());
                }
            }
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => {}
            Err(e) => return Err(e.into()),
        }
        match OpenOptions::new().read(true).open(&path) {
            Ok(mut file) => {
                let mut marker = [0u8; STAMP.len()];
                file.read_exact(&mut marker)?;
                if marker != STAMP {
                    return Err("reserved test is not generated fixture output".into());
                }
            }
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => {}
            Err(e) => return Err(e.into()),
        }
    }
    let prefix = r#"import { test, expect } from "bun:test";
import { gcTick } from "harness";
const emitter = "#;
    let suffix = r#";

test.each(["stdout", "stderr"])("completed subprocess is collectable after late %s getter", async channel => {
  const weak = [];
  const codes = await Promise.all(Array.from({ length: 6 }, async () => {
    const proc = Bun.spawn([emitter, channel === "stderr" ? "--stderr" : "--stdout"], {
      stdin: "ignore",
      stdout: channel === "stdout" ? "pipe" : "ignore",
      stderr: channel === "stderr" ? "pipe" : "ignore",
      windowsHide: true,
    });
    weak.push(new WeakRef(proc));
    try {
      const exitCode = await proc.exited;
      const output = await new Response(channel === "stdout" ? proc.stdout : proc.stderr).text();
      expect(output).toBe("synthetic subprocess output");
      expect(exitCode).toBe(0);
      return exitCode;
    } finally {
      if (proc.exitCode === null) {
        proc.kill();
        await proc.exited;
      }
    }
  }));
  expect(codes).toEqual([0, 0, 0, 0, 0, 0]);
  expect(weak).toHaveLength(6);
  const deadline = performance.now() + 1000;
  let live = 6;
  do {
    await gcTick();
    live = weak.filter(ref => ref.deref() !== undefined).length;
  } while (live && performance.now() < deadline);
  expect(live).toBe(0);
});
"#;
    let mut file = OpenOptions::new()
        .create_new(!reuse)
        .create(reuse)
        .truncate(reuse)
        .write(true)
        .open(path)?;
    file.write_all(STAMP)?;
    file.write_all(prefix.as_bytes())?;
    file.write_all(emitter.as_bytes())?;
    file.write_all(suffix.as_bytes())?;
    Ok(())
}
